sys_script_include.script:
var IncidentsForUser = Class.create();
IncidentsForUser.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getRecentIncidents: function() {
        var userId = gs.getUserID();
        var incGR = new GlideRecordSecure('incident');
        incGR.addQuery('caller_id', userId);
        incGR.orderByDesc('sys_updated_on');
        incGR.setLimit(10);
        incGR.query();

        var incidents = [];
        while (incGR.next()) {
            incidents.push({
                number: incGR.getValue('number'),
                short_description: incGR.getValue('short_description'),
                state: incGR.getValue('state'),
                sys_updated_on: incGR.getValue('sys_updated_on')
            });
        }
        return JSON.stringify(incidents);
    }

});
